import { Product } from '../../domain/entities/Product';
import type { ProductRepository } from '../../domain/repositories/ProductRepository';
import { ConflictError } from '../errors/ApplicationError';
import type { AddProductCommand, StockLevelDto } from './ProductDtos';
import { toStockLevelDto } from './ProductMapper';

export interface AddProduct {
  execute(command: AddProductCommand): StockLevelDto;
}

/** Adds a new product to the catalogue with its opening stock. */
export class AddProductUseCase implements AddProduct {
  constructor(private readonly products: ProductRepository) {}

  execute(command: AddProductCommand): StockLevelDto {
    const product = Product.create(command);
    if (this.products.findById(product.id) !== undefined) {
      throw new ConflictError(`Product ${product.id} already exists`);
    }
    this.products.save(product);
    return toStockLevelDto(product);
  }
}

=====SOURCE-END=====

