import type { ProductRepository } from '../../domain/repositories/ProductRepository';
import { AddProductUseCase, type AddProduct } from './AddProductUseCase';
import { ListCatalogueUseCase, type ListCatalogue } from './ListCatalogueUseCase';
import { ListStockLevelsUseCase, type ListStockLevels } from './ListStockLevelsUseCase';

export interface CatalogueUseCases {
  readonly addProduct: AddProduct;
  readonly listCatalogue: ListCatalogue;
  readonly listStockLevels: ListStockLevels;
}

export interface CatalogueModuleDependencies {
  readonly products: ProductRepository;
}

export function createCatalogueUseCases(deps: CatalogueModuleDependencies): CatalogueUseCases {
  return {
    addProduct: new AddProductUseCase(deps.products),
    listCatalogue: new ListCatalogueUseCase(deps.products),
    listStockLevels: new ListStockLevelsUseCase(deps.products),
  };
}

